mapper.select:
SELECT
    (
        SELECT COUNT(*)
        FROM ORDERS o
        WHERE o.ordered_at >= #{todayStartUtc}
          AND o.ordered_at < #{tomorrowStartUtc}
    ) AS today_order_count,

    (
        SELECT COALESCE(SUM(p.amount), 0)
        FROM PAYMENT p
        INNER JOIN ORDERS o
            ON o.order_id = p.order_id
        WHERE p.payment_status = 'PAID'
          AND o.ordered_at >= #{todayStartUtc}
          AND o.ordered_at < #{tomorrowStartUtc}
    ) AS today_revenue,

    (
        SELECT COUNT(*)
        FROM MEMBER m
        WHERE m.created_at >= #{todayStartUtc}
          AND m.created_at < #{tomorrowStartUtc}
    ) AS new_member_count,

    (
        SELECT COUNT(*)
        FROM ORDERS o
        WHERE o.order_status = 'PENDING'
    ) AS pending_order_count
